<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientClientUriAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientClientUriAccessor trait.
 *
 * Covers null default, string/VO assignment via withClientUri,
 * getClientUri/clientUri accessors, and isClientUriChanged with/without original.
 */
class TrustedClientClientUriAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withClientUri creates a new instance with the ClientUri set
     * from a string value, and getClientUri returns the primitive string.
     */
    public function testWithClientUriFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientClientUriAccessorUnitTest();

        // Act
        $result = $holder->withClientUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getClientUri());
    }
    /**
     * Asserts that withclientUri has access to the value object
     * from a string value, and getClientUri returns the primitive string.
     */
    public function testWithClientUriFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientClientUriAccessorUnitTest();

        // Act
        $result = $holder->withClientUri('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->clientUri()->value());
    }
    public function testChangedClientUri(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientClientUriAccessorUnitTest();
        $original = $holder->withClientUri('one');
        $same = $holder->withClientUri('one');
        $modified = $holder->withClientUri('other');

        // Act
        $unchanged = $holder->isClientUriChanged();
        $withSame = $original->isClientUriChanged($same);
        $withDiferent = $original->isClientUriChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientClientUriAccessorUnitTest
{
    use TrustedClientClientUriAccessor;
}
